CREATE TEMPORARY VIEW feature_scenario_tag_mapping_${grass_region_without_quote} AS
SELECT
    feature_detail
    ,operation
    ,FILTER(scenario_tags, value -> value NOT LIKE 'Page %') AS scenario_tags
    ,ROW_NUMBER() OVER (PARTITION BY feature_detail ORDER BY local_hour DESC) AS recency_rank
FROM
    srdi_mart.dim_sr_data_warehouse_feature_scenario_tag_mapping
WHERE
    operation IN ('click', 'impression', 'view', 'ppv', 'order')
    AND grass_region = ${grass_region}
    AND local_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW feature_list_${grass_region_without_quote} AS
SELECT
    feature AS feature_detail
    ,mapping_detail AS feature
    ,mapping_general AS feature_group
FROM
    mkplsearch_data_product.shopee_snr_team_oa_feature_list;

--sql_divide_splitter--

CREATE TEMPORARY VIEW platform_data_parse_${grass_region_without_quote} AS
SELECT
    user_id
    ,feature_detail
    ,COALESCE(CAST(is_ads AS STRING), 'false') AS is_ads
    ,page_type
    ,target_type
    ,place_order_gmv
    ,place_order_gmv_local
    ,operation
    ,operation_cnt
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    operation IN ('click', 'impression', 'view', 'ppv', 'order')
    AND feature_detail != ''
    AND grass_region = ${grass_region}
    AND local_date = ${local_date}
UNION ALL
SELECT
    user_id
    ,source1_feature_detail AS feature_detail
    ,COALESCE(CAST(source1_is_ads AS STRING), 'false') AS is_ads
    ,source1_page_type AS page_type
    ,source1_target_type AS target_type
    ,place_order_gmv
    ,place_order_gmv_local
    ,operation
    ,operation_cnt
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    operation IN ('ppv', 'order')
    AND source1_feature_detail != ''
    AND source1_feature_detail != feature_detail
    AND grass_region = ${grass_region}
    AND local_date = ${local_date}
UNION ALL
SELECT
    user_id
    ,source2_feature_detail AS feature_detail
    ,COALESCE(CAST(source2_is_ads AS STRING), 'false') AS is_ads
    ,source2_page_type AS page_type
    ,source2_target_type AS target_type
    ,place_order_gmv
    ,place_order_gmv_local
    ,operation
    ,operation_cnt
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    operation IN ('ppv', 'order')
    AND source2_feature_detail != ''
    AND source2_feature_detail != source1_feature_detail
    AND source2_feature_detail != feature_detail
    AND grass_region = ${grass_region}
    AND local_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW platform_data_grouped_${grass_region_without_quote} AS
SELECT
    user_id
    ,feature_detail
    ,IF(is_ads IS NOT NULL, is_ads, '__ALL__') AS is_ads
    ,SUM(CASE WHEN operation = 'impression' THEN operation_cnt ELSE NULL END) AS imp_cnt
    ,SUM(CASE WHEN operation = 'click' THEN operation_cnt ELSE NULL END) AS click_cnt
    ,SUM(CASE WHEN operation = 'view'
        AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill', 'image_search', 'shopee_mart_search')
        THEN operation_cnt ELSE NULL END) AS srp_pv
    ,SUM(CASE WHEN operation = 'ppv' THEN operation_cnt ELSE NULL END) AS ppv_cnt
    ,SUM(CASE WHEN operation = 'order' THEN operation_cnt ELSE NULL END) AS place_order_cnt
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv_local ELSE NULL END) AS place_order_gmv_local
    ,SUM(CASE WHEN operation = 'order' THEN place_order_gmv ELSE NULL END) AS place_order_gmv
FROM
    platform_data_parse_${grass_region_without_quote}
GROUP BY GROUPING SETS
    ((user_id, feature_detail, is_ads), (user_id, feature_detail));

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_user_feature_civ_order_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    user_id
    ,feature
    ,a.feature_detail
    ,feature_group
    ,is_ads
    ,COALESCE(imp_cnt, 0)
    ,COALESCE(click_cnt, 0)
    ,COALESCE(ppv_cnt, 0)
    ,COALESCE(srp_pv, 0)
    ,COALESCE(place_order_cnt, 0)
    ,COALESCE(place_order_gmv_local, 0)
    ,COALESCE(place_order_gmv, 0)
    ,scenario_tags
FROM
    platform_data_grouped_${grass_region_without_quote} a
LEFT JOIN
    feature_list_${grass_region_without_quote} b
ON
    a.feature_detail = b.feature_detail
LEFT JOIN
    feature_scenario_tag_mapping_${grass_region_without_quote} c
ON
    a.feature_detail = c.feature_detail
WHERE
    c.recency_rank = 1;
